#if UNITY_EDITOR
using System.Collections.Generic;
using UnityEditor;
using UnityEngine;
using UnityEngine.Rendering;
using UnityEngine.Rendering.Universal;

namespace Zombies55.EditorTools
{
    // Everything the Graphics settings need on disk, regenerated by every scene build:
    //   * one URP pipeline asset per quality level (PC_RPAsset = High, PC_RPAsset_Low / _Medium / _Ultra) listed in QualitySettings,
    //     so URP's shader stripping keeps every variant each level needs (soft shadow quality, upscaler, shadow cascades);
    //   * one renderer asset per ambient occlusion setting (PC_Renderer = High, plus Off / Low / Medium / Ultra), listed in every
    //     pipeline asset, so SSAO quality is switched with the public UniversalAdditionalCameraData.SetRenderer and the sample-count
    //     variants are kept;
    //   * a volume profile that is never loaded at runtime: the stripper scans every VolumeProfile in Assets, so it keeps the bloom HQ
    //     and camera motion blur variants that only the Ultra preset or a manual setting turns on;
    //   * the Clutter / ClutterDecal layers and the pass that puts decorative street detail on them (see StreetDetail).
    public static partial class SceneBuilder
    {
        const string QualityDir = "Assets/Settings/Quality";
        const string HighAssetPath = "Assets/Settings/PC_RPAsset.asset";
        const string HighRendererPath = "Assets/Settings/PC_Renderer.asset";
        const string CoveragePath = QualityDir + "/GraphicsVariantCoverage.asset";

        // Renderer list order in every pipeline asset (GraphicsApplier.AoRendererIndex mirrors it).
        static readonly string[] AoRendererSuffix = { null, "Off", "Low", "Medium", "Ultra" };

        // Per level: render scale, upscaler (0 auto, 3 FSR), main shadow map, cascades, distance, soft shadow quality (1..3), additional light atlas
        struct LevelDef
        {
            public string Name; public float Scale; public int Upscaler, ShadowRes, Cascades; public float Distance; public int Soft, AddRes;
            public float LodBias; public int Skin, Aniso, RaycastBudget, MipLimit;
        }

        static readonly LevelDef[] Levels =
        {
            new LevelDef { Name = "Low", Scale = 0.67f, Upscaler = 3, ShadowRes = 1024, Cascades = 2, Distance = 40f, Soft = 1, AddRes = 1024, LodBias = 1f, Skin = 2, Aniso = 1, RaycastBudget = 16, MipLimit = 1 },
            new LevelDef { Name = "Medium", Scale = 0.85f, Upscaler = 3, ShadowRes = 2048, Cascades = 3, Distance = 70f, Soft = 2, AddRes = 1024, LodBias = 1.5f, Skin = 2, Aniso = 2, RaycastBudget = 64, MipLimit = 0 },
            new LevelDef { Name = "High", Scale = 1f, Upscaler = 0, ShadowRes = 4096, Cascades = 4, Distance = 140f, Soft = 3, AddRes = 2048, LodBias = 2f, Skin = 4, Aniso = 2, RaycastBudget = 256, MipLimit = 0 },
            new LevelDef { Name = "Ultra", Scale = 1.25f, Upscaler = 0, ShadowRes = 8192, Cascades = 4, Distance = 200f, Soft = 3, AddRes = 4096, LodBias = 3f, Skin = 4, Aniso = 2, RaycastBudget = 512, MipLimit = 0 },
        };

        static string LevelAssetPath(string level) => level == "High" ? HighAssetPath : QualityDir + "/PC_RPAsset_" + level + ".asset";

        static void ConfigureGraphicsAssets()
        {
            EnsureFolder(QualityDir);
            var renderers = BuildAoRenderers();
            var assets = new List<UniversalRenderPipelineAsset>();
            foreach (var lv in Levels)
            {
                string path = LevelAssetPath(lv.Name);
                if (lv.Name != "High" && AssetDatabase.LoadAssetAtPath<UniversalRenderPipelineAsset>(path) == null)
                    AssetDatabase.CopyAsset(HighAssetPath, path);
                var asset = AssetDatabase.LoadAssetAtPath<UniversalRenderPipelineAsset>(path);
                var so = new SerializedObject(asset);
                void SetI(string n, int v) { var p = so.FindProperty(n); if (p == null) throw new System.InvalidOperationException("URP asset has no " + n); p.intValue = v; }
                void SetF(string n, float v) { var p = so.FindProperty(n); if (p == null) throw new System.InvalidOperationException("URP asset has no " + n); p.floatValue = v; }
                SetF("m_RenderScale", lv.Scale);
                SetI("m_UpscalingFilter", lv.Upscaler);
                SetI("m_MainLightShadowmapResolution", lv.ShadowRes);
                SetI("m_ShadowCascadeCount", lv.Cascades);
                SetF("m_ShadowDistance", lv.Distance);
                SetI("m_SoftShadowQuality", lv.Soft);
                SetI("m_AdditionalLightsShadowmapResolution", lv.AddRes);
                SetI("m_RequireOpaqueTexture", 0);   // nothing in Assets samples _CameraOpaqueTexture: the full-screen copy was wasted
                SetI("m_DefaultRendererIndex", 0);
                var list = so.FindProperty("m_RendererDataList");
                list.arraySize = renderers.Length;
                for (int i = 0; i < renderers.Length; i++) list.GetArrayElementAtIndex(i).objectReferenceValue = renderers[i];
                so.ApplyModifiedPropertiesWithoutUndo();
                EditorUtility.SetDirty(asset);
                assets.Add(asset);
            }
            BuildCoverageProfile();
            ConfigureQualityLevels(assets);
            EnsureClutterLayers();
            AssetDatabase.SaveAssets();
        }

        // PC_Renderer (High: bilateral blur, 8 samples) first, then Off / Low / Medium / Ultra copies with only the SSAO feature changed.
        static UniversalRendererData[] BuildAoRenderers()
        {
            var result = new UniversalRendererData[AoRendererSuffix.Length];
            result[0] = AssetDatabase.LoadAssetAtPath<UniversalRendererData>(HighRendererPath);
            for (int i = 1; i < AoRendererSuffix.Length; i++)
            {
                string path = QualityDir + "/PC_Renderer_AO_" + AoRendererSuffix[i] + ".asset";
                if (AssetDatabase.LoadAssetAtPath<UniversalRendererData>(path) == null) AssetDatabase.CopyAsset(HighRendererPath, path);
                var rd = AssetDatabase.LoadAssetAtPath<UniversalRendererData>(path);
                ScriptableRendererFeature ssao = null;
                foreach (var f in rd.rendererFeatures) if (f != null && f.GetType().Name == "ScreenSpaceAmbientOcclusion") { ssao = f; break; }
                if (ssao == null) throw new System.InvalidOperationException(path + " has no SSAO feature");
                var sso = new SerializedObject(ssao);
                var s = sso.FindProperty("m_Settings");
                // AOSampleOption: High 12, Medium 8, Low 4. BlurQuality: High bilateral, Medium gaussian, Low kawase. NormalQuality: Low, Medium, High.
                int samples = 1, blur = 0, normals = 1; bool down = false;
                switch (AoRendererSuffix[i])
                {
                    case "Low": samples = 2; blur = 2; down = true; break;
                    case "Medium": samples = 2; blur = 1; break;
                    case "Ultra": samples = 0; blur = 0; normals = 2; break;
                }
                s.FindPropertyRelative("Samples").intValue = samples;
                s.FindPropertyRelative("BlurQuality").intValue = blur;
                s.FindPropertyRelative("NormalSamples").intValue = normals;
                s.FindPropertyRelative("Downsample").boolValue = down;
                sso.ApplyModifiedPropertiesWithoutUndo();
                ssao.SetActive(AoRendererSuffix[i] != "Off");
                EditorUtility.SetDirty(ssao);
                EditorUtility.SetDirty(rd);
                result[i] = rd;
            }
            return result;
        }

        static void BuildCoverageProfile()
        {
            var profile = AssetDatabase.LoadAssetAtPath<VolumeProfile>(CoveragePath);
            if (profile == null)
            {
                profile = ScriptableObject.CreateInstance<VolumeProfile>();
                AssetDatabase.CreateAsset(profile, CoveragePath);
            }
            var mb = GetOrAdd<MotionBlur>(profile);
            mb.mode.Override(MotionBlurMode.CameraOnly);
            mb.quality.Override(MotionBlurQuality.Medium);
            mb.intensity.Override(0.5f);
            var bloom = GetOrAdd<Bloom>(profile);
            bloom.intensity.Override(0.1f);
            bloom.highQualityFiltering.Override(true);
            EditorUtility.SetDirty(profile);
        }

        // Levels: Mobile (never in a Standalone build), Low, Medium, High (the old "PC" level), Ultra.
        static void ConfigureQualityLevels(List<UniversalRenderPipelineAsset> assets)
        {
            var qs = AssetDatabase.LoadAllAssetsAtPath("ProjectSettings/QualitySettings.asset")[0];
            var so = new SerializedObject(qs);
            var levels = so.FindProperty("m_QualitySettings");
            int pc = -1;
            for (int i = 0; i < levels.arraySize; i++)
            {
                string n = levels.GetArrayElementAtIndex(i).FindPropertyRelative("name").stringValue;
                if (n == "PC" || n == "High") pc = i;
            }
            if (pc < 0) throw new System.InvalidOperationException("QualitySettings has no PC / High level");
            while (levels.arraySize < 5) levels.InsertArrayElementAtIndex(pc);
            // After duplicating, element 0 is Mobile and 1..4 are copies of PC: name and fill each one.
            for (int k = 0; k < 4; k++)
            {
                var e = levels.GetArrayElementAtIndex(1 + k);
                var lv = Levels[k];
                e.FindPropertyRelative("name").stringValue = lv.Name;
                e.FindPropertyRelative("customRenderPipeline").objectReferenceValue = assets[k];
                e.FindPropertyRelative("lodBias").floatValue = lv.LodBias;
                e.FindPropertyRelative("skinWeights").intValue = lv.Skin;
                e.FindPropertyRelative("anisotropicTextures").intValue = lv.Aniso;
                e.FindPropertyRelative("particleRaycastBudget").intValue = lv.RaycastBudget;
                e.FindPropertyRelative("globalTextureMipmapLimit").intValue = lv.MipLimit;
            }
            var defaults = so.FindProperty("m_PerPlatformDefaultQuality");
            for (int i = 0; i < defaults.arraySize; i++)
            {
                var el = defaults.GetArrayElementAtIndex(i);
                if (el.FindPropertyRelative("first").stringValue == "Standalone") el.FindPropertyRelative("second").intValue = 3; // High
            }
            so.FindProperty("m_CurrentQuality").intValue = 3;
            so.ApplyModifiedPropertiesWithoutUndo();
            EditorUtility.SetDirty(qs);
        }

        // ------------------------------------------------------------------ clutter layers

        static void EnsureClutterLayers()
        {
            var tm = AssetDatabase.LoadAllAssetsAtPath("ProjectSettings/TagManager.asset")[0];
            var so = new SerializedObject(tm);
            var layers = so.FindProperty("layers");
            void Set(int index, string name)
            {
                var p = layers.GetArrayElementAtIndex(index);
                if (p.stringValue != name) p.stringValue = name;
            }
            Set(GameLayers.Clutter, "Clutter");
            Set(GameLayers.ClutterDecal, "ClutterDecal");
            so.ApplyModifiedPropertiesWithoutUndo();
            EditorUtility.SetDirty(tm);
        }

        // Decorative street detail without a collider moves to a clutter layer so the camera can cull it by distance (Camera.layerCullDistances,
        // set by StreetDetail from the STREET DETAIL setting). Objects with colliders (bins, cover, signs people can hit) stay on Default:
        // bullets, the flare rays and the NavMesh keep seeing them. Decals: dirt, street noise (posters, tags, stickers, tufts, door litter).
        // Clutter: steam, vault grates, cross-street cables, cardboard, bags and other collider-free litter.
        static void AssignClutterLayers()
        {
            int decals = 0, clutter = 0;
            SplitBigMeshes(_props.Find("Dirt"), 38f);
            void Walk(Transform root, int layer, ref int counter)
            {
                if (root == null) return;
                foreach (var r in root.GetComponentsInChildren<Renderer>(true))
                {
                    if (r.GetComponent<Collider>() != null) continue;
                    r.gameObject.layer = layer;
                    counter++;
                }
            }
            Walk(_props.Find("Dirt"), GameLayers.ClutterDecal, ref decals);
            Walk(_props.Find("StreetNoise"), GameLayers.ClutterDecal, ref decals);
            Walk(_props.Find("TrashBags"), GameLayers.Clutter, ref clutter);
            var density = _props.Find("Density");
            if (density != null)
                foreach (var g in new[] { "Steam", "CrossCables", "VaultGrates", "Litter" })
                    Walk(density.Find(g), GameLayers.Clutter, ref clutter);
            Debug.Log("Street detail layers: " + decals + " decal renderers, " + clutter + " clutter renderers");
        }

        // A decal mesh that spans the whole city cannot be distance culled: split it into one mesh per cell (triangles by centroid).
        static void SplitBigMeshes(Transform root, float cell)
        {
            if (root == null) return;
            foreach (var mf in root.GetComponentsInChildren<MeshFilter>(true))
            {
                var mesh = mf.sharedMesh;
                var mr = mf.GetComponent<MeshRenderer>();
                if (mesh == null || mr == null || mesh.bounds.size.x < cell * 1.5f && mesh.bounds.size.z < cell * 1.5f) continue;
                var verts = mesh.vertices; var uv = mesh.uv; var nrm = mesh.normals; var tris = mesh.triangles;
                var groups = new Dictionary<Vector2Int, List<int>>();
                for (int t = 0; t < tris.Length; t += 3)
                {
                    var c = (verts[tris[t]] + verts[tris[t + 1]] + verts[tris[t + 2]]) / 3f;
                    var key = new Vector2Int(Mathf.FloorToInt(c.x / cell), Mathf.FloorToInt(c.z / cell));
                    if (!groups.TryGetValue(key, out var l)) groups[key] = l = new List<int>();
                    l.Add(tris[t]); l.Add(tris[t + 1]); l.Add(tris[t + 2]);
                }
                EnsureFolder(GeneratedDir);
                foreach (var kv in groups)
                {
                    var map = new Dictionary<int, int>();
                    var v = new List<Vector3>(); var u = new List<Vector2>(); var n = new List<Vector3>(); var idx = new List<int>();
                    foreach (int old in kv.Value)
                    {
                        if (!map.TryGetValue(old, out int ni))
                        {
                            ni = v.Count; map[old] = ni;
                            v.Add(verts[old]); if (uv.Length > old) u.Add(uv[old]); if (nrm.Length > old) n.Add(nrm[old]);
                        }
                        idx.Add(ni);
                    }
                    string name = mesh.name + "_" + kv.Key.x + "_" + kv.Key.y;
                    string path = GeneratedDir + "/" + name + ".asset";
                    var part = AssetDatabase.LoadAssetAtPath<Mesh>(path);
                    if (part == null) { part = new Mesh { name = name }; AssetDatabase.CreateAsset(part, path); }
                    part.Clear();
                    part.indexFormat = UnityEngine.Rendering.IndexFormat.UInt32;
                    part.SetVertices(v); if (u.Count == v.Count) part.SetUVs(0, u); if (n.Count == v.Count) part.SetNormals(n);
                    part.SetTriangles(idx, 0);
                    part.RecalculateBounds();
                    EditorUtility.SetDirty(part);
                    var go = new GameObject(name);
                    go.transform.SetParent(mf.transform.parent, false);
                    go.transform.localPosition = mf.transform.localPosition;
                    go.transform.localRotation = mf.transform.localRotation;
                    go.transform.localScale = mf.transform.localScale;
                    go.AddComponent<MeshFilter>().sharedMesh = part;
                    var pr = go.AddComponent<MeshRenderer>();
                    pr.sharedMaterial = mr.sharedMaterial;
                    pr.shadowCastingMode = mr.shadowCastingMode;
                    pr.receiveShadows = mr.receiveShadows;
                }
                Object.DestroyImmediate(mf.gameObject);
            }
        }
    }
}
#endif
